rtk env PATH="$PWD/.venv/bin:$PATH" python -c 'import ast, io, re, subprocess, sys, tokenize
OWNERS = (ast.Module, ast.ClassDef, ast.FunctionDef, ast.AsyncFunctionDef)
PAT = re.compile(r"#\s*(?:noqa\b|type:\s*ignore\b|pragma:\s*no cover\b|pyright:|mypy:|ruff:|pylint:|(?:fmt|isort):\s*(?:on|off|skip)\b|nosec\b|coding[:=]|[A-Za-z][\w-]*-ok:)", re.I)
class Strip(ast.NodeTransformer):
    def generic_visit(self, node):
        node = super().generic_visit(node)
        if isinstance(node, OWNERS) and node.body and isinstance(node.body[0], ast.Expr) and isinstance(node.body[0].value, ast.Constant) and isinstance(node.body[0].value.value, str):
            node.body.pop(0)
        return node
def src(ref, path):
    return subprocess.check_output(["git", "show", f"{ref}:{path}"], text=True)
def norm(text, path):
    tree = Strip().visit(ast.parse(text, filename=path, type_comments=True))
    for node in ast.walk(tree):
        if isinstance(node, ast.TypeIgnore): node.lineno = 0
    return ast.dump(tree, annotate_fields=True, include_attributes=False)
def directives(text):
    lines = text.splitlines()
    selected = [lines[tok.start[0]-1] for tok in tokenize.generate_tokens(io.StringIO(text).readline) if tok.type == tokenize.COMMENT and PAT.search(tok.string)]
    return (lines[0] if lines and lines[0].startswith("#!") else ""), selected
bad_ast, bad_directives = [], []
for path in sys.argv[1:]:
    before, after = src("HEAD^", path), src("HEAD", path)
    if norm(before, path) != norm(after, path): bad_ast.append(path)
    if directives(before) != directives(after): bad_directives.append(path)
assert not bad_ast, f"non-docstring AST changes: {bad_ast}"
assert not bad_directives, f"directive/shebang changes: {bad_directives}"' tests/e2e/_toolchain.py tests/e2e/conftest.py tests/e2e/test_editor_batch_library.py tests/e2e/test_editor_browser.py tests/e2e/test_editor_e2e.py tests/e2e/test_editor_library.py tests/e2e/test_toolchain_provisioning.py
